// Percentages are applied as integer percent points — `base * 1.1` yields
// 110.00000000000001 for a sword and breaks the ceil.
const applyPercent = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const quote = (items: { type: string }[]): number => {
  const basePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );

  const firstInsuranceSurcharge = applyPercent(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return Math.ceil(basePremium + firstInsuranceSurcharge) + PROCESSING_FEE;
};
